// app/(admin)/dashboard/page.tsx
'use client'
import { Ad } from '../../../models/ad'
import { connectDB } from '../../../lib/db'
import { verifyUserFromCookie } from '../../../lib/auth'
import Link from 'next/link'

export default async function AdminDashboard() {
  const user = await verifyUserFromCookie()

  if (!user) {
    return (
      <div className="p-10 text-center text-red-600">
        Akses ditolak. Silakan{' '}
        <Link href="/login" className="underline text-blue-600">
          login
        </Link>{' '}
        terlebih dahulu.
      </div>
    )
  }

  try {
    await connectDB()
    const ads = await Ad.find().sort({ createdAt: -1 })

    return (
      <div className="p-6 max-w-4xl mx-auto">
        <h1 className="text-2xl font-bold text-qgreen mb-6">📋 Dashboard Admin</h1>

        <div className="flex justify-between mb-4">
          <Link href="/admin/upload">
            <button className="bg-qgreen text-white px-5 py-2 rounded hover:bg-green-700 transition">
              ➕ Tambah Iklan
            </button>
          </Link>

          <Link href="/api/logout">
            <button className="text-sm text-red-600 hover:underline">
              Logout
            </button>
          </Link>
        </div>

        {ads.length === 0 ? (
          <p className="text-gray-500">Belum ada iklan.</p>
        ) : (
          <ul className="space-y-4">
            {ads.map((ad: any) => (
              <li key={ad._id.toString()} className="card border p-4 rounded shadow">
                <h2 className="text-lg font-semibold text-qgreen">{ad.title}</h2>
                <p className="text-sm text-gray-600 mb-2">{ad.description}</p>
                <div className="flex justify-between items-center">
                  <Link
                    href={`/ads/${ad._id.toString()}`}
                    className="text-blue-600 hover:underline text-sm"
                  >
                    🔍 Lihat Detail
                  </Link>
                  <form action={`/api/ads/${ad._id}`} method="POST">
                    <button
                      type="submit"
                      className="text-red-500 text-sm hover:underline"
                      onClick={(e) => {
                        if (!confirm('Yakin hapus iklan ini?')) e.preventDefault()
                      }}
                    >
                      ❌ Hapus
                    </button>
                  </form>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    )
  } catch (error) {
    console.error('❌ Gagal mengambil iklan:', error)
    return (
      <div className="p-10 text-center text-red-600">
        Gagal mengambil data iklan.
      </div>
    )
  }
}
